  auto loc = std::locale(std::locale(), new numpunct<char>());
  std::cout << "[" << fmt::format(loc, "{:19.3Lf}", -119.921) << "]\n";
  std::cout << "[" << fmt::format(loc, "{:19.3Lf}", 2194.139) << "]\n";
